before:
Complete local Kotlin/JVM example; the app itself does not execute it:
```kotlin
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.collect

fun main() {
    runBlocking {
        var starts = 0
        val values = flow { starts++; emit(3) }
        println(starts)
        values.collect { println(it) }
        values.collect { println(it) }
        println(starts)
    }
}
```

